import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.B6bX9x3v.js";const b=JSON.parse('{"title":"审计日志","description":"","frontmatter":{},"headers":[],"relativePath":"modules/hub0004.md","filePath":"modules/hub0004.md","lastUpdated":1787231210000}'),a={name:"modules/hub0004.md"};function h(l,t,c,n,s,i){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="审计日志" tabindex="-1">审计日志 <a class="header-anchor" href="#审计日志" aria-label="Permalink to &quot;审计日志&quot;">​</a></h1><p>查看控制台<strong>写操作审计</strong>：谁、在哪个模块、对哪条数据、做了新增 / 修改 / 删除 / 回滚 / 授权 / 导出 / 登录 / 踢会话。数据来自 <code>HUB_AUTH_AUDIT_LOG</code>。业务模块 <code>SetEvent</code> 放入对象后，由全局审计中间件在请求结束时落库。鉴权中间件不参与。本页不能改或删记录。导出按当前筛选条件由服务端流式生成 CSV，不限制条数，浏览器只负责下载。</p><hr><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><strong>审计日志</strong>面向安全管理员与合规排查，用来：</p><ul><li><strong>追溯变更</strong>：定位某次用户、角色、资源、路由等配置是谁改的。</li><li><strong>核对授权</strong>：筛选动作「授权」，查看角色资源或用户角色的授予记录。</li><li><strong>核对登录</strong>：筛选「登录 / 登录失败 / 踢会话」。验证码、单次密码或账号错误不记审计（在登录日志里）；审计里的登录失败只表示账号进入冷却。</li><li><strong>区分流量日志</strong>：网关访问日志在「网关管理 → 网关日志管理」；本页只记管理面操作。</li></ul><p>写接口成功记 <code>result=Y</code>，业务失败或按钮无权限记 <code>result=N</code>。查询本页本身不写审计；<strong>导出</strong>会记一条 <code>EXPORT</code>。</p><hr><h2 id="访问入口" tabindex="-1">访问入口 <a class="header-anchor" href="#访问入口" aria-label="Permalink to &quot;访问入口&quot;">​</a></h2><p>侧栏 <strong>系统设置</strong> → <strong>审计日志</strong>。</p><p>已有库需执行对应库的 <code>patch_auth_resource_20260820_hub0004.sql</code>，并确认已有 <code>HUB_AUTH_AUDIT_LOG</code>。导出按钮另执行 <code>patch_auth_resource_20260820_hub0004_export.sql</code>。超级管理员与只读角色会补上本模块授权；其他角色在「角色管理」中勾选 <code>hub0004</code>（导出需 <code>hub0004:export</code>）。</p><hr><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to &quot;使用流程&quot;">​</a></h2><ol><li>进入页面后默认加载<strong>最近 7 天</strong>的记录。</li><li>按动作、模块、操作人缩小范围；需要目标名称、资源编码、客户端 IP 时点 <strong>更多条件</strong>。</li><li>点 <strong>查询</strong>。清空时间范围可查全部历史（数据量大时可能较慢）。</li><li>行上 <strong>右键 → 查看详情</strong>，核对目标 ID、请求路径与补充说明。</li><li>点 <strong>导出</strong>，服务端按当前筛选用数据库游标逐行写出 CSV 并下载（不限制条数，适合大数据）。无数据时会提示失败，不会下空文件。</li></ol><hr><h2 id="筛选条件" tabindex="-1">筛选条件 <a class="header-anchor" href="#筛选条件" aria-label="Permalink to &quot;筛选条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>时间范围</td><td>按记录创建时间过滤；默认最近 7 天，可改快捷项或自定义。</td></tr><tr><td>动作</td><td>新增、修改、删除、回滚、授权、导出、登录、登录失败、踢会话。</td></tr><tr><td>模块</td><td>产生该操作的控制台模块（如用户管理 <code>hub0002</code>）。</td></tr><tr><td>操作人</td><td>按用户名模糊匹配。</td></tr><tr><td>结果（更多）</td><td>成功或失败。</td></tr><tr><td>目标类型 / 名称 / ID（更多）</td><td>被操作对象，如用户、角色、路由。</td></tr><tr><td>资源编码（更多）</td><td>按钮或接口资源码，如 <code>hub0002:edit</code>。</td></tr><tr><td>用户 ID / 客户端 IP（更多）</td><td>精确用户 ID；IP 支持模糊匹配。</td></tr></tbody></table><hr><h2 id="列表字段" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段" aria-label="Permalink to &quot;列表字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>操作时间</td><td>审计写入时间。</td></tr><tr><td>操作人</td><td>当时登录用户名。</td></tr><tr><td>动作</td><td>新增 / 修改 / 删除 / 回滚 / 授权 / 导出 / 登录 / 踢会话。</td></tr><tr><td>模块</td><td>模块编码及名称。</td></tr><tr><td>目标类型 / 名称 / ID</td><td>被改对象，由业务 <code>SetEvent</code> 填写。</td></tr><tr><td>资源编码</td><td>触发该次写操作的权限码。</td></tr><tr><td>结果</td><td>成功或失败。</td></tr><tr><td>客户端 IP / 请求路径</td><td>来源地址与管理端 API 路径。</td></tr></tbody></table><hr><h2 id="详情" tabindex="-1">详情 <a class="header-anchor" href="#详情" aria-label="Permalink to &quot;详情&quot;">​</a></h2><p>详情按基本信息、操作对象、请求信息分组。补充说明来自业务 <code>SetEvent</code>；失败时改为错误信息。若为 JSON 会格式化展示。口令、验证码等敏感字段不会写入。审计记录不可修改、不可删除。</p><hr><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><p>本模块按钮：<code>hub0004:view</code>、<code>hub0004:search</code>、<code>hub0004:reset</code>、<code>hub0004:export</code>。有模块权限即可调列表与详情接口；导出需 <code>hub0004:export</code>。看不到菜单时，请管理员在角色中授予 <code>hub0004</code>。</p>',26)])])}const _=d(a,[["render",h]]);export{b as __pageData,_ as default};
